<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\ValidationException;
class AuthController extends Controller { public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|unique:users,email','phone'=>'nullable|string|max:30','password'=>'required|string|min:8']); $u=User::create(['name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>Hash::make($d['password']),'role'=>'customer']); return response()->json(['user'=>$u,'token'=>$u->createToken('mobile')->plainTextToken],201);} public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required']); $u=User::where('email',$d['email'])->first(); if(!$u||!Hash::check($d['password'],$u->password)) throw ValidationException::withMessages(['email'=>'Invalid credentials.']); if(!$u->is_active) abort(403,'Account is disabled.'); return ['user'=>$u->load('branch'),'token'=>$u->createToken('mobile')->plainTextToken];} public function me(Request $r){return $r->user()->load('branch');} public function logout(Request $r){$r->user()->currentAccessToken()?->delete(); return ['message'=>'Logged out'];}}